import { makeAutoObservable, runInAction } from 'mobx';

export type Todo = { id: string; title: string; done: boolean };

export class TodoStore {
  todos: Todo[] = [];
  filter: 'all' | 'open' | 'done' = 'all';
  loading = false;

  constructor() {
    makeAutoObservable(this);   // observables, actions, and computeds inferred
  }

  get visibleTodos() {
    if (this.filter === 'open') return this.todos.filter((t) => !t.done);
    if (this.filter === 'done') return this.todos.filter((t) => t.done);
    return this.todos;
  }

  add(title: string) {
    this.todos.push({ id: crypto.randomUUID(), title, done: false });
  }

  toggle(id: string) {
    const todo = this.todos.find((t) => t.id === id);
    if (todo) todo.done = !todo.done;
  }

  async load() {
    this.loading = true;
    try {
      const res = await fetch('/api/todos');
      const data = await res.json();
      runInAction(() => { this.todos = data; this.loading = false; });
    } catch {
      runInAction(() => { this.loading = false; });
    }
  }
}

export const todoStore = new TodoStore();

import { observer } from 'mobx-react-lite';
import { todoStore } from './stores/todoStore';

export const TodoList = observer(function TodoList() {
  const [title, setTitle] = useState('');

  return (
    <section>
      <form onSubmit={(e) => { e.preventDefault(); todoStore.add(title); setTitle(''); }}>
        <input value={title} onChange={(e) => setTitle(e.target.value)} />
      </form>
      {todoStore.loading && <p>Loading…</p>}
      <ul>
        {todoStore.visibleTodos.map((todo) => (
          <li key={todo.id} onClick={() => todoStore.toggle(todo.id)}>
            {todo.done ? '✓' : '○'} {todo.title}
          </li>
        ))}
      </ul>
    </section>
  );
});
